@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

:root {
  --bg-base: #141414;
  --bg-darker: #000000;
  --brand-red: #e50914;
  --brand-red-hover: #c11119;
  --text-primary: #ffffff;
  --text-secondary: rgba(255, 255, 255, 0.7);
  --border-color: rgba(255, 255, 255, 0.3);
  --surface: rgba(45, 45, 45, 0.6);
  --surface-hover: rgba(65, 65, 65, 0.8);
  --focus-ring: 0 0 0 4px rgba(229, 9, 20, 0.4);
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
  --spacing-1: 4px;
  --spacing-2: 8px;
  --spacing-3: 16px;
  --spacing-4: 24px;
  --spacing-5: 32px;
  --spacing-6: 48px;
  --spacing-8: 64px;
  --spacing-10: 80px;
  --spacing-12: 120px;
  --border-radius: 4px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  line-height: 1.2;
  font-weight: 800;
}

a {
  color: var(--text-primary);
  text-decoration: none;
  transition: opacity 0.2s ease;
}

a:hover {
  opacity: 0.8;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

button:focus-visible, a:focus-visible, input:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--border-radius);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-4);
}

.btn-primary {
  background-color: var(--brand-red);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: var(--border-radius);
  transition: background-color 0.2s ease, transform 0.1s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn-primary:hover {
  background-color: var(--brand-red-hover);
}

.btn-primary:active {
  transform: scale(0.98);
}

.btn-large {
  font-size: 1.25rem;
  padding: 14px 32px;
}

/* Header */
.header {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 10;
  padding: var(--spacing-4) 0;
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 2.25rem;
  font-weight: 900;
  color: var(--brand-red);
  letter-spacing: -1px;
  line-height: 1;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
}

.lang-select {
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 8px 32px 8px 12px;
  border-radius: var(--border-radius);
  font-size: 0.875rem;
  appearance: none;
  background-image: url('data:image/svg+xml;utf8,<svg fill="white" height="24" viewBox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M7 10l5 5 5-5z"/></svg>');
  background-repeat: no-repeat;
  background-position: right 4px center;
}

/* Hero */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 140px var(--spacing-4) var(--spacing-10);
  background: 
    linear-gradient(to top, var(--bg-base) 0%, rgba(20, 20, 20, 0.4) 50%, rgba(0,0,0,0.8) 100%),
    url('https://images.unsplash.com/photo-1598899134739-24c46f58b8c0?auto=format&fit=crop&q=80&w=2000') center/cover no-repeat;
}

.hero::after {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  background: rgba(0,0,0,0.4);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  letter-spacing: -1.5px;
}

.hero-subtitle {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 500;
}

.email-form {
  margin-top: var(--spacing-4);
}

.email-form-prompt {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-3);
  color: var(--text-primary);
}

.email-input-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-2);
  max-width: 600px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .email-input-group {
    flex-direction: row;
    gap: var(--spacing-2);
  }
}

.email-input {
  flex: 1;
  padding: 16px var(--spacing-3);
  background: rgba(22, 22, 22, 0.7);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  color: var(--text-primary);
  font-size: 1rem;
  transition: border-color 0.2s ease, background 0.2s ease;
}

.email-input:focus {
  border-color: var(--brand-red);
  background: rgba(22, 22, 22, 0.9);
}

.email-input::placeholder {
  color: var(--text-secondary);
}

/* Section Common */
.section {
  padding: var(--spacing-10) 0;
  border-bottom: 8px solid #222;
}

.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: var(--spacing-6);
  letter-spacing: -1px;
}

/* Trending */
.trending {
  padding-bottom: var(--spacing-10);
}

.carousel-container {
  position: relative;
  display: flex;
  align-items: center;
  margin: 0 calc(var(--spacing-4) * -1);
  padding: 0 var(--spacing-4);
}

@media (min-width: 1200px) {
  .carousel-container {
    margin: 0;
    padding: 0;
  }
}

.carousel {
  display: flex;
  gap: var(--spacing-4);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: var(--spacing-4) 0;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.carousel::-webkit-scrollbar {
  display: none;
}

.carousel-item {
  scroll-snap-align: start;
  flex: 0 0 160px;
  position: relative;
  border-radius: var(--border-radius);
  overflow: hidden;
  transition: transform 0.3s ease;
}

@media (min-width: 768px) {
  .carousel-item {
    flex: 0 0 200px;
  }
}

.carousel-item:hover {
  transform: scale(1.05);
  z-index: 2;
}

.carousel-item-img {
  width: 100%;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  background-color: var(--surface);
  border-radius: var(--border-radius);
}

.carousel-item-rank {
  position: absolute;
  bottom: -10px;
  left: -10px;
  font-size: 6rem;
  font-weight: 900;
  color: #000;
  -webkit-text-stroke: 2px var(--text-secondary);
  line-height: 1;
  letter-spacing: -4px;
  z-index: 2;
}

.carousel-nav {
  position: absolute;
  right: var(--spacing-4);
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(0,0,0,0.7);
  border: 1px solid var(--border-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 3;
  color: white;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.carousel-container:hover .carousel-nav {
  opacity: 1;
}

@media (max-width: 768px) {
  .carousel-nav {
    display: none;
  }
}

/* Features */
.features-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-4);
}

@media (min-width: 768px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.feature-card {
  background: linear-gradient(135deg, rgba(35, 35, 35, 0.8) 0%, rgba(20, 20, 20, 0.9) 100%);
  padding: var(--spacing-5);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  position: relative;
  min-height: 280px;
}

.feature-title {
  font-size: 1.5rem;
  margin-bottom: var(--spacing-2);
}

.feature-desc {
  color: var(--text-secondary);
  font-size: 1rem;
}

.feature-icon {
  position: absolute;
  bottom: var(--spacing-5);
  right: var(--spacing-5);
  color: var(--brand-red);
  opacity: 0.8;
}

/* FAQ */
.faq-list {
  max-width: 900px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-2);
}

.faq-item {
  background: var(--surface);
  transition: background 0.2s ease;
}

.faq-item:hover {
  background: var(--surface-hover);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px;
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-icon {
  font-size: 2rem;
  transition: transform 0.3s ease;
}

.faq-item.active .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s cubic-bezier(0, 1, 0, 1);
  padding: 0 24px;
  font-size: 1.125rem;
  color: var(--text-secondary);
}

.faq-item.active .faq-answer {
  max-height: 1000px;
  padding-bottom: 24px;
  transition: max-height 0.5s ease-in-out, padding 0.5s ease-in-out;
}

/* CTA Bottom */
.cta-section {
  text-align: center;
  padding: var(--spacing-12) 0;
}

/* Footer */
.footer {
  padding: var(--spacing-10) 0;
  color: var(--text-secondary);
}

.footer-contact {
  margin-bottom: var(--spacing-5);
}

.footer-contact a {
  color: var(--text-secondary);
  text-decoration: underline;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-4);
  margin-bottom: var(--spacing-6);
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.footer-link {
  color: var(--text-secondary);
  font-size: 0.875rem;
  text-decoration: underline;
}

.footer-bottom {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
  align-items: flex-start;
}

.footer-note {
  font-size: 0.875rem;
}

/* Login Page */
.login-body {
  background-color: var(--bg-darker);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

@media (min-width: 768px) {
  .login-body {
    background: 
      linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.5) 100%),
      url('https://images.unsplash.com/photo-1598899134739-24c46f58b8c0?auto=format&fit=crop&q=80&w=2000') center/cover no-repeat;
  }
}

.login-header {
  padding: var(--spacing-4) 5%;
  position: relative;
  z-index: 2;
}

.login-container {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-4);
  z-index: 2;
}

.login-box {
  width: 100%;
  max-width: 450px;
  background-color: var(--bg-darker);
  padding: var(--spacing-8) var(--spacing-8) var(--spacing-12);
  border-radius: var(--border-radius);
}

@media (min-width: 768px) {
  .login-box {
    background-color: rgba(0,0,0,0.75);
  }
}

.login-title {
  font-size: 2rem;
  margin-bottom: var(--spacing-4);
}

.login-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
}

.login-input {
  width: 100%;
  padding: 16px;
  background: #333;
  border: 1px solid transparent;
  border-radius: var(--border-radius);
  color: white;
  font-size: 1rem;
}

.login-input:focus {
  background: #444;
  border-color: white;
}

.login-btn {
  width: 100%;
  margin-top: var(--spacing-2);
}

.login-help-toggle {
  color: var(--text-secondary);
  font-size: 0.875rem;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  text-decoration: underline;
  margin-top: var(--spacing-4);
}

.login-help-content {
  display: none;
  margin-top: var(--spacing-3);
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.login-help-content.show {
  display: block;
}

.login-footer {
  background: rgba(0,0,0,0.75);
  padding: var(--spacing-6) 5%;
  border-top: 1px solid var(--border-color);
  z-index: 2;
}
